const listEl=document.getElementById('list');const nameEl=document.getElementById('name');const msg=document.getElementById('msg');const emptyEl=document.getElementById('empty');const countEl=document.getElementById('count');let items=[];let revs={};
async function load(){const r=await tessera.call('data.read',{});items=r.data.items||[];revs=r.revisions.items||{};render();}
async function patch(ops){msg.textContent='';try{await tessera.call('data.patch',{operations:ops});await load();return true;}catch(e){msg.textContent='That change could not be saved. Please try again.';await load();return false;}}
function render(){listEl.textContent='';for(const it of items){const li=document.createElement('li');li.setAttribute('data-hook','item');if(it.packed)li.className='done';const lab=document.createElement('label');const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!it.packed;cb.addEventListener('change',()=>{patch([{op:'replace',collection:'items',id:it.id,revisionCount:revs[it.id],fields:{packed:cb.checked}}]);});const nm=document.createElement('span');nm.className='nm';nm.textContent=it.name;lab.appendChild(cb);lab.appendChild(nm);const rm=document.createElement('button');rm.type='button';rm.setAttribute('data-hook','item-remove');rm.textContent='Remove';rm.setAttribute('aria-label','Remove '+it.name);rm.addEventListener('click',()=>{patch([{op:'remove',collection:'items',id:it.id,revisionCount:revs[it.id]}]);});li.appendChild(lab);li.appendChild(rm);listEl.appendChild(li);}
emptyEl.hidden=items.length>0;const p=items.filter(i=>i.packed).length;countEl.textContent=items.length?p+' of '+items.length+' packed':'';}
async function add(){const v=nameEl.value.trim();if(!v){msg.textContent='Type an item name first.';nameEl.focus();return;}const ok=await patch([{op:'add',collection:'items',record:{name:v,packed:false}}]);if(ok){nameEl.value='';}nameEl.focus();}
document.getElementById('add').addEventListener('click',add);nameEl.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add();}});
load();
